<?php
namespace App\Filament\Resources;
use App\Filament\Resources\StudentClubResource\Pages;use App\Models\StudentClub;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class StudentClubResource extends Resource{protected static ?string $model=StudentClub::class;protected static bool $shouldRegisterNavigation=false;protected static ?string $modelLabel='объединение';protected static ?string $pluralModelLabel='Кружки и актив';public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('type')->label('Тип')->options(['club'=>'Кружок','section'=>'Секция','student_government'=>'Самоуправление','volunteer'=>'Волонтёрство'])->required(),Forms\Components\TextInput::make('title')->label('Название')->required(),Forms\Components\Textarea::make('description')->label('Описание')->columnSpan('full'),Forms\Components\TextInput::make('schedule')->label('Расписание'),Forms\Components\TextInput::make('place')->label('Место')])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('title')->label('Название')->searchable(),Tables\Columns\BadgeColumn::make('type')->label('Тип')->enum(['club'=>'Кружок','section'=>'Секция','student_government'=>'Самоуправление','volunteer'=>'Волонтёрство']),Tables\Columns\TextColumn::make('schedule')->label('Расписание'),Tables\Columns\TextColumn::make('place')->label('Место')])->actions([Tables\Actions\EditAction::make()->label('Изменить'),Tables\Actions\Action::make('archive')->label('Закрыть')->color('danger')->requiresConfirmation()->action(fn($record)=>$record->update(['active'=>0]))]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->where('active',1);}public static function getPages():array{return['index'=>Pages\ListStudentClubs::route('/'),'create'=>Pages\CreateStudentClub::route('/create'),'edit'=>Pages\EditStudentClub::route('/{record}/edit')];}}
